"""Liveness and readiness probes."""

from __future__ import annotations

from fastapi import APIRouter, Request

router = APIRouter(prefix="/health", tags=["health"])


@router.get("/live")
async def live() -> dict[str, str]:
    return {"status": "ok"}


@router.get("/ready")
async def ready(request: Request) -> dict[str, object]:
    state = request.app.state.app_state
    detail: dict[str, object] = {}
    os_ok = False
    # Generated by GitHub Copilot - Nov-01-2026
    redis_required = state.yaml_config.cache.backend == "redis"
    redis_ok = not redis_required
    try:
        os_ok = bool(state.opensearch.ping(request_timeout=5))
        detail["opensearch"] = {"ping": os_ok}
    except Exception as e:  # noqa: BLE001
        detail["opensearch"] = {"error": str(e)}
    # Generated by GitHub Copilot - Nov-01-2026
    if redis_required:
        try:
            pong = await state.redis.ping()
            redis_ok = bool(pong)
            detail["redis"] = {"ping": pong}
        except Exception as e:  # noqa: BLE001
            detail["redis"] = {"error": str(e)}
    else:
        detail["redis"] = {"enabled": False}

    return {"ready": os_ok and redis_ok, "components": detail}
